-- ============================================================
-- league_data_cba.sql — CBA 真实数据入库（由 scripts_cloudbase/build-cba-db.py 生成）
-- 数据源：腾讯体育（data/cba.json）· 赛程比分页 CBA 段（data/matches.json）
-- 前置：db/migrate-day22-league-season.sql（season / zone 列）
-- 执行顺序：schema.sql → league_data.sql → league_data_nba.sql → 本文件
--   （league_data.sql 里有一段 cbaleague 的 CBA 26-27，须被本文件覆盖）
-- 可重复执行：先清空 league_id=cba / league=CBA 的行，再插入
-- 规模：league_schedule 972 · league_standings 20 · league_brackets 2 · matches 20
-- ============================================================

BEGIN;

-- ---------- 1. 联赛维度表（与真实数据的 desc / tabs 对齐）----------
-- 用 upsert：维度表已有 cba 这一行，重跑不该报主键冲突
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, sport = EXCLUDED.sport,
  emoji = EXCLUDED.emoji, description = EXCLUDED.description,
  tabs = EXCLUDED.tabs, updated_at = EXCLUDED.updated_at;

-- ---------- 2. 清空 CBA 旧数据（含 league_data.sql 灌的 cbaleague 赛程）----------
DELETE FROM public.league_schedule WHERE league_id = 'cba';
DELETE FROM public.league_standings WHERE league_id = 'cba';
DELETE FROM public.league_players WHERE league_id = 'cba';
DELETE FROM public.league_brackets WHERE league_id = 'cba';
DELETE FROM public.matches WHERE league = 'CBA';

-- ---------- 3. league_schedule（两个赛季 972 场）----------

-- ---------- 4. league_standings（25-26 常规赛 20 队，无分区）----------

-- ---------- 5. league_brackets（晋级图 + 季后赛对阵）----------

-- ---------- 6. matches（赛程比分页 CBA 段 20 条）----------

COMMIT;

-- 收尾自检
SELECT 'league_schedule' t, count(*) FROM public.league_schedule WHERE league_id='cba'
UNION ALL SELECT 'league_standings', count(*) FROM public.league_standings WHERE league_id='cba'
UNION ALL SELECT 'league_brackets',  count(*) FROM public.league_brackets  WHERE league_id='cba'
UNION ALL SELECT 'matches(CBA)',     count(*) FROM public.matches        WHERE league='CBA';
SELECT season, count(*) FROM public.league_schedule WHERE league_id='cba' GROUP BY season ORDER BY season;
SELECT season, count(*) FROM public.league_standings WHERE league_id='cba' GROUP BY season ORDER BY season;
